suspend fun complete(id: String) {
    db.withTransaction {
        tasks.update(id) { it.copy(done = true, updatedAt = clock.millis(), syncStatus = SyncStatus.PENDING) }
        outbox.add(OutboxEntity(id = UUID.randomUUID().toString(), entityId = id, op = Op.UPDATE))
    }
    syncScheduler.requestSync()
}
